const qs=(s,c=document)=>c.querySelector(s),qsa=(s,c=document)=>[...c.querySelectorAll(s)];
const monitorDialog=qs('#monitorDialog'),detailDialog=qs('#detailDialog'),toast=qs('#toast');
const STORAGE={monitors:'acw.monitors',reviewed:'acw.reviewed'};
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
let customMonitors=read(STORAGE.monitors,[]),currentChange=null;
const notify=(title,detail='')=>{toast.querySelector('b').textContent=title;toast.querySelector('small').textContent=detail;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3500)};
const updateMonitorCount=()=>{const total=6+customMonitors.length;qs('#monitorCount').textContent=total;qs('#navMonitorCount').textContent=total;qs('#monitorGrowth').textContent=`↑ ${2+customMonitors.length}`};
const applyFilters=()=>{const level=qs('.filter.active').dataset.filter,term=qs('#changeSearch').value.toLowerCase().trim();qsa('.change-row').forEach(row=>{const levelMatch=level==='all'||row.dataset.level===level;const textMatch=!term||row.textContent.toLowerCase().includes(term);row.classList.toggle('hidden',!levelMatch||!textMatch)})};
qs('#newMonitor').addEventListener('click',()=>monitorDialog.showModal());
qs('.mobile-menu').addEventListener('click',()=>qs('.sidebar').classList.toggle('open'));
qsa('.sidebar a').forEach(a=>a.addEventListener('click',()=>qs('.sidebar').classList.remove('open')));
qsa('.filter').forEach(btn=>btn.addEventListener('click',()=>{qsa('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');applyFilters()}));
qs('#changeSearch').addEventListener('input',applyFilters);
qsa('.change-row').forEach((row,index)=>{row.dataset.changeId=`change-${index}`;row.classList.toggle('reviewed',read(STORAGE.reviewed,[]).includes(row.dataset.changeId));row.addEventListener('click',()=>{currentChange=row;qs('#detailTitle').textContent=row.dataset.title;qs('#detailText').textContent=row.dataset.detail;qs('#markReviewed').textContent=row.classList.contains('reviewed')?'Marcar como pendiente':'Marcar como revisado';detailDialog.showModal()})});
qsa('#detailDialog .close, #detailDialog .close-action').forEach(b=>b.addEventListener('click',()=>detailDialog.close()));
qs('#reviewCritical').addEventListener('click',()=>{qs('[data-filter="critical"]').click();qs('#monitors').scrollIntoView({behavior:'smooth'})});
qs('#viewAll').addEventListener('click',()=>qsa('.filter')[0].click());
qs('#markReviewed').addEventListener('click',()=>{if(!currentChange)return;const reviewed=new Set(read(STORAGE.reviewed,[])),wasReviewed=reviewed.has(currentChange.dataset.changeId);wasReviewed?reviewed.delete(currentChange.dataset.changeId):reviewed.add(currentChange.dataset.changeId);write(STORAGE.reviewed,[...reviewed]);currentChange.classList.toggle('reviewed',!wasReviewed);detailDialog.close();notify(wasReviewed?'Cambio marcado como pendiente':'Cambio revisado',wasReviewed?'Volvió a la cola de revisión.':'Guardado en este navegador.')});
qs('#monitorForm').addEventListener('submit',e=>{e.preventDefault();const name=qs('#apiName').value.trim(),url=qs('#apiUrl').value.trim();if(!name||!url)return;customMonitors.push({id:crypto.randomUUID?.()||Date.now().toString(),name,url,createdAt:new Date().toISOString()});write(STORAGE.monitors,customMonitors);updateMonitorCount();monitorDialog.close();notify(`${name} agregado`,'El primer escaneo ya está en curso.');e.target.reset()});
monitorDialog.addEventListener('click',e=>{if(e.target===monitorDialog)monitorDialog.close()});detailDialog.addEventListener('click',e=>{if(e.target===detailDialog)detailDialog.close()});
let seconds=272;setInterval(()=>{seconds=seconds?seconds-1:900;const m=String(Math.floor(seconds/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');qs('#countdown').textContent=`${m}:${s}`},1000);
updateMonitorCount();
